const body = $input.first()?.json?.body ?? $input.first()?.json ?? {};
const query = (body.query || body.q || '').trim();
const count = Math.min(Number(body.count) || 5, 10);
const safe  = body.safe !== false;
if (!query) throw new Error('query parameter is required');
return [{ json: { query, count, safe } }];

const raw = $input.first()?.json?.stdout ?? '';
const params = $('Parse Parameters').first().json;
let ddg;
try { ddg = JSON.parse(raw); } catch { ddg = null; }
const results = [];
if (ddg) {
  if (ddg.AbstractText) results.push({ title: ddg.Heading || params.query, snippet: ddg.AbstractText, url: ddg.AbstractURL || ddg.AbstractSource });
  const topics = ddg.RelatedTopics || [];
  for (const t of topics.slice(0, params.count - results.length)) {
    if (t.Text && t.FirstURL) results.push({ title: t.Text.substring(0, 80), snippet: t.Text, url: t.FirstURL });
  }
}
return [{ json: { success: true, query: params.query, count: results.length, results } }];
